        // ===== PWA: Service Worker (offline desteği) =====
        // DÜZELTME: eskiden blob: URL ile register ediliyordu — Chrome/Android bunu
        // "URL protocol not supported" hatasıyla SESSİZCE reddediyor (.catch(()=>{}) yutuyordu),
        // yani service worker HİÇBİR ZAMAN gerçekten kurulmuyordu ve uygulama kabuğu (app.js/sync.js/
        // styles.css) sıfır sinyal olan bir yerde (yarışma alanı gibi) hiç açılamıyordu.
        // Artık gerçek bir /sw.js dosyası olarak register ediliyor.
        if('serviceWorker' in navigator) {
            navigator.serviceWorker.register('/sw.js').catch(()=>{});
            // Bildirime tıklanınca (uygulama kapalıyken/arka plandayken) sw.js buraya postMessage atar.
            navigator.serviceWorker.addEventListener('message', (e) => {
                let msg = e.data; if(!msg || msg.source !== 'dagsk-push') return;
                if(msg.data && msg.data.kind === 'duello-davet') {
                    setTimeout(() => {
                        if(msg.action === 'reddet') dueloDavetiYanitla(msg.data, false);
                        else dueloDavetGoster(msg.data); // 'kabul' veya doğrudan bildirime tıklama -> daveti göster, kullanıcı onaylasın
                    }, 400);
                }
            });
        }
        // ===== PWA: Kurulum teklifi =====
        let pwaPrompt = null;
        window.addEventListener('beforeinstallprompt', (e) => { e.preventDefault(); pwaPrompt = e; try { document.getElementById('pwa-banner').style.display='flex'; } catch(_) {} });
        function pwaKur() { if(pwaPrompt) { pwaPrompt.prompt(); pwaPrompt.userChoice.then(() => { pwaPrompt=null; try { document.getElementById('pwa-banner').style.display='none'; } catch(_) {} }); } }
        // iOS Safari'de beforeinstallprompt YOK — Apple programatik kurulum teklifine izin vermiyor, bu
        // yüzden elle talimatlı ayrı bir banner (bkz. index.html #ios-ekle-banner).
        function _iosSafariPWADegilMi() {
            let iOS = /iPad|iPhone|iPod/.test(navigator.userAgent) || (navigator.platform === 'MacIntel' && navigator.maxTouchPoints > 1);
            return iOS && window.navigator.standalone !== true;
        }
        function iosEkleBannerGoster() {
            try {
                if(!_iosSafariPWADegilMi() || localStorage.getItem('dag_ios_ekle_kapatildi')) return;
                let b = document.getElementById('ios-ekle-banner'); if(b) b.style.display = 'flex';
            } catch(e) {}
        }
        function iosEkleBannerKapat() {
            try { localStorage.setItem('dag_ios_ekle_kapatildi', '1'); } catch(e) {}
            let b = document.getElementById('ios-ekle-banner'); if(b) b.style.display = 'none';
        }
        const TEAM_COLORS = ['#ec4899', '#8b5cf6', '#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#14b8a6', '#f43f5e', '#a855f7', '#0ea5e9'];
        let aktifSezonAdi = localStorage.getItem('dag_sezon_adi') || 'Aktif Sezon';
        let aktifSezonBaslangic = localStorage.getItem('dag_sezon_baslangic') || null;
        let aktifSezonBitis = localStorage.getItem('dag_sezon_bitis') || null;

        function sezonAyarla() {
            girdiIste('📅 Sezon adı (örn: 2025 Bahar Sezonu):', aktifSezonAdi, (ad) => {
                if(!ad) return;
                aktifSezonAdi = ad.trim();
                localStorage.setItem('dag_sezon_adi', aktifSezonAdi);
                girdiIste('📅 Sezon başlangıç tarihi (YYYY-AA-GG):', aktifSezonBaslangic||bugunISO(), (bas) => {
                    aktifSezonBaslangic = bas||bugunISO();
                    localStorage.setItem('dag_sezon_baslangic', aktifSezonBaslangic);
                    girdiIste('📅 Sezon bitiş tarihi (YYYY-AA-GG):', aktifSezonBitis||'', (bit) => {
                        aktifSezonBitis = bit||null;
                        if(aktifSezonBitis) localStorage.setItem('dag_sezon_bitis', aktifSezonBitis);
                        else localStorage.removeItem('dag_sezon_bitis');
                        showToast('✅ Sezon bilgileri güncellendi', 'success');
                        sezonSayaciniGuncelle();
                        // Firestore'a yaz — tüm cihazlar görsün
                        _sezonBulutaYaz();
                    });
                });
            });
        }

        function _sezonBulutaYaz() {
            if(!bulutHazir || !dbBulut) return;
            dbBulut.collection('kulup').doc('sezon_bilgisi').set({
                ad: aktifSezonAdi,
                baslangic: aktifSezonBaslangic || '',
                bitis: aktifSezonBitis || '',
                guncelleme: Date.now()
            }).catch(() => {});
        }

        function _sezonBuluttanYukle() {
            if(!bulutHazir || !dbBulut) return;
            // Sezon bilgisini Firestore'dan çek
            dbBulut.collection('kulup').doc('sezon_bilgisi').get().then(doc => {
                if(!doc.exists) return;
                let d = doc.data();
                if(d.ad) { aktifSezonAdi = d.ad; localStorage.setItem('dag_sezon_adi', d.ad); }
                if(d.baslangic) { aktifSezonBaslangic = d.baslangic; localStorage.setItem('dag_sezon_baslangic', d.baslangic); }
                aktifSezonBitis = d.bitis || null;
                if(aktifSezonBitis) localStorage.setItem('dag_sezon_bitis', aktifSezonBitis);
                else localStorage.removeItem('dag_sezon_bitis');
                sezonSayaciniGuncelle();
            }).catch(() => {});
            // Canlı dinle — biri güncellerse diğerleri de görsün
            dbBulut.collection('kulup').doc('sezon_bilgisi').onSnapshot(doc => {
                if(!doc.exists) return;
                let d = doc.data();
                if(!d || !d.ad) return;
                let degisti = (d.ad !== aktifSezonAdi || d.baslangic !== aktifSezonBaslangic || d.bitis !== aktifSezonBitis);
                if(!degisti) return;
                aktifSezonAdi = d.ad;
                aktifSezonBaslangic = d.baslangic || null;
                aktifSezonBitis = d.bitis || null;
                localStorage.setItem('dag_sezon_adi', aktifSezonAdi);
                if(aktifSezonBaslangic) localStorage.setItem('dag_sezon_baslangic', aktifSezonBaslangic);
                if(aktifSezonBitis) localStorage.setItem('dag_sezon_bitis', aktifSezonBitis);
                else localStorage.removeItem('dag_sezon_bitis');
                sezonSayaciniGuncelle();
            }, () => {});
        }

        function sezonWidgetHTML(kompakt) {
            let simdi = new Date();
            let basTarih = aktifSezonBaslangic ? new Date(aktifSezonBaslangic) : null;
            let bitTarih = aktifSezonBitis ? new Date(aktifSezonBitis) : null;
            let kalanGun = bitTarih ? Math.max(0, Math.ceil((bitTarih - simdi) / 86400000)) : null;
            let gecenGun = basTarih ? Math.max(0, Math.floor((simdi - basTarih) / 86400000)) : null;
            let yuzde = (basTarih && bitTarih) ? Math.min(100, Math.max(0, Math.round(((simdi-basTarih)/(bitTarih-basTarih))*100))) : null;
            let renk = kalanGun === null ? 'var(--accent-orange)' : kalanGun > 30 ? 'var(--neon-green)' : kalanGun > 7 ? '#f59e0b' : 'var(--neon-red)';
            let emoji = kalanGun === null ? '🏆' : kalanGun > 30 ? '🟢' : kalanGun > 7 ? '⚡' : '🔥';
            let kalanTxt = kalanGun === null ? 'Devam ediyor' : kalanGun === 0 ? 'Bugün bitiyor!' : kalanGun + ' gün kaldı';
            if(kompakt) {
                return '<div onclick="sekmeAc(\'klasman\')" style="cursor:pointer;background:linear-gradient(135deg,rgba(255,98,0,0.1),rgba(59,130,246,0.06));border:1px solid rgba(255,98,0,0.25);border-radius:12px;padding:10px 14px;margin-bottom:12px;display:flex;align-items:center;gap:10px;">'
                    + '<div style="font-size:26px;">' + emoji + '</div>'
                    + '<div style="flex:1;min-width:0;">'
                    + '<div style="font-size:10px;font-weight:800;color:var(--text-muted);letter-spacing:1px;">AKTİF SEZON</div>'
                    + '<div style="font-size:14px;font-weight:900;color:var(--accent-orange);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + aktifSezonAdi + '</div>'
                    + (basTarih ? '<div style="font-size:11px;color:var(--text-muted);">' + basTarih.toLocaleDateString('tr-TR') + (bitTarih ? ' → ' + bitTarih.toLocaleDateString('tr-TR') : '') + '</div>' : '')
                    + '</div>'
                    + '<div style="text-align:right;flex-shrink:0;">'
                    + '<div style="font-size:18px;font-weight:900;color:' + renk + ';">' + (kalanGun !== null ? kalanGun : '∞') + '</div>'
                    + '<div style="font-size:9px;color:var(--text-muted);font-weight:700;">' + (kalanGun !== null ? 'GÜN KALDI' : 'AÇIK') + '</div>'
                    + '</div></div>'
                    + (yuzde !== null ? '<div style="background:rgba(0,0,0,0.25);border-radius:6px;height:4px;overflow:hidden;margin:-6px 0 12px;"><div style="height:100%;background:' + renk + ';border-radius:6px;width:' + yuzde + '%;"></div></div>' : '');
            }
            return '<div style="background:linear-gradient(135deg,rgba(255,98,0,0.1),rgba(0,0,0,0.15));border:1px solid rgba(255,98,0,0.3);border-radius:16px;padding:16px;margin-bottom:14px;">'
                + '<div style="display:flex;align-items:center;gap:12px;margin-bottom:10px;">'
                + '<div style="font-size:32px;">' + emoji + '</div>'
                + '<div style="flex:1;"><div style="font-size:10px;font-weight:800;color:var(--text-muted);letter-spacing:1.5px;margin-bottom:2px;">AKTİF SEZON</div>'
                + '<div style="font-size:18px;font-weight:900;color:var(--accent-orange);">' + aktifSezonAdi + '</div></div>'
                + (kalanGun !== null
                    ? '<div style="text-align:center;background:rgba(0,0,0,0.3);border-radius:12px;padding:8px 14px;flex-shrink:0;"><div style="font-size:28px;font-weight:900;color:' + renk + ';line-height:1;">' + kalanGun + '</div><div style="font-size:9px;color:var(--text-muted);font-weight:800;letter-spacing:1px;">GÜN KALDI</div></div>'
                    : '<div style="text-align:center;background:rgba(255,98,0,0.1);border:1px solid rgba(255,98,0,0.3);border-radius:12px;padding:8px 14px;flex-shrink:0;"><div style="font-size:18px;">∞</div><div style="font-size:9px;color:var(--accent-orange);font-weight:800;">AÇIK SEZON</div></div>')
                + '</div>'
                + (basTarih ? '<div style="display:flex;gap:10px;margin-bottom:10px;">'
                    + '<div style="text-align:center;flex:1;background:rgba(0,0,0,0.2);border-radius:10px;padding:8px;">'
                    + '<div style="font-size:10px;color:var(--text-muted);font-weight:700;margin-bottom:2px;">BAŞLANGIÇ</div>'
                    + '<div style="font-size:13px;font-weight:800;">' + basTarih.toLocaleDateString('tr-TR') + '</div>'
                    + (gecenGun !== null ? '<div style="font-size:10px;color:var(--neon-green);">' + gecenGun + '. gün</div>' : '')
                    + '</div>'
                    + (bitTarih ? '<div style="text-align:center;flex:1;background:rgba(0,0,0,0.2);border-radius:10px;padding:8px;">'
                        + '<div style="font-size:10px;color:var(--text-muted);font-weight:700;margin-bottom:2px;">BİTİŞ</div>'
                        + '<div style="font-size:13px;font-weight:800;">' + bitTarih.toLocaleDateString('tr-TR') + '</div>'
                        + '<div style="font-size:10px;color:' + renk + ';">' + kalanTxt + '</div></div>' : '')
                    + '</div>' : '')
                + (yuzde !== null ? (function() {
                    // Eğlenceli emoji track: 10 segmentli yol
                    let seg = Math.round(yuzde / 10);
                    let okcu = '🏹';
                    let hedef = '🎯';
                    let yol = '';
                    for(let i=0;i<10;i++) {
                        if(i < seg) yol += '<span style="opacity:0.4;">·</span>';
                        else if(i === seg) yol += '<span style="font-size:16px;">' + okcu + '</span>';
                        else yol += '<span style="opacity:0.2;">·</span>';
                    }
                    let milestones = [{p:25,e:'⚡'},{p:50,e:'🔥'},{p:75,e:'💪'},{p:100,e:'🏆'}];
                    let msHtml = milestones.map(m =>
                        '<div style="position:absolute;left:'+m.p+'%;transform:translateX(-50%);top:-8px;font-size:'+(yuzde>=m.p?'14px':'11px')+';opacity:'+(yuzde>=m.p?'1':'0.3')+';">'+m.e+'</div>'
                    ).join('');
                    return '<div style="margin-top:4px;">'
                        + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">'
                        + '<span style="font-size:10px;color:var(--text-muted);font-weight:700;">SEZON İLERLEMESİ</span>'
                        + '<span style="font-size:12px;font-weight:900;color:' + renk + ';">%' + yuzde + '</span>'
                        + '</div>'
                        + '<div style="position:relative;padding-top:18px;">'
                        + '<div style="position:relative;">' + msHtml + '</div>'
                        + '<div style="background:rgba(0,0,0,0.35);border-radius:10px;height:12px;overflow:hidden;">'
                        + '<div style="height:100%;background:linear-gradient(90deg,#ff6200,' + renk + ');border-radius:10px;width:' + yuzde + '%;transition:width 0.8s;position:relative;">'
                        + '<div style="position:absolute;right:-1px;top:50%;transform:translateY(-50%);font-size:14px;">🏹</div>'
                        + '</div></div>'
                        + '</div>'
                        + '<div style="display:flex;justify-content:space-between;margin-top:6px;font-size:10px;color:var(--text-muted);">'
                        + '<span>🚀 Başladı</span><span style="color:' + renk + ';font-weight:700;">' + (yuzde>=100?'🏆 Bitti!':kalanTxt) + '</span><span>🎯 Bitiş</span>'
                        + '</div></div>';
                })() : '')
                + (kalanGun !== null && kalanGun <= 14 ? '<div style="margin-top:10px;text-align:center;font-size:12px;font-weight:800;color:' + renk + ';padding:8px;background:rgba(0,0,0,0.2);border-radius:8px;">' + (kalanGun===0?'⚡ Bugün son gün!':kalanGun<=7?'🔥 Sadece '+kalanGun+' gün kaldı!':'⏳ '+kalanGun+' gün içinde bitiyor') + '</div>' : '')
                + '</div>';
        }
        function sezonSayaciniGuncelle() {
            let el = document.getElementById('sezon-sayac-widget');
            if(el) el.innerHTML = sezonWidgetHTML(false);
            let el2 = document.getElementById('sezon-sayac-ana');
            if(el2) el2.innerHTML = sezonWidgetHTML(true);
        }
        function sezonSayaciBaslat() {
            sezonSayaciniGuncelle();
            setInterval(sezonSayaciniGuncelle, 60000);
        }
        let _sonrakiDersCache = {}; // grup -> {slots, fetchT}
        function birSonrakiDersHesapla(slots) {
            if(!slots || !slots.length) return null;
            let simdi = new Date();
            let enYakin = null, enYakinFark = Infinity;
            slots.forEach(s => {
                let parcalar = (s.baslangicSaat || '').split(':').map(Number);
                let sh = parcalar[0], sm = parcalar[1];
                if(isNaN(sh) || isNaN(sm)) return;
                for(let hafta = 0; hafta < 2; hafta++) {
                    let gunFarki = (s.gun - simdi.getDay() + 7) % 7 + hafta * 7;
                    let hedefTarih = new Date(simdi.getFullYear(), simdi.getMonth(), simdi.getDate() + gunFarki, sh, sm, 0, 0);
                    // Bu SPESİFİK oluşum tek seferlik iptal edilmişse (bkz. antrenman_programi_istisna)
                    // aday olarak sayılmaz — bir sonraki geçerli oluşum doğal olarak öne çıkar.
                    if((s.istisnalar||[]).some(function(i){ return i.tarih === bsIsoTarih(hedefTarih); })) continue;
                    let fark = hedefTarih.getTime() - simdi.getTime();
                    if(fark >= -5 * 60000 && fark < enYakinFark) { enYakinFark = fark; enYakin = { slot: s, tarih: hedefTarih }; }
                }
            });
            return enYakin;
        }
        // Tüm kulübün slotları + her slotun katılımcı listesi — sporcu tarafında ARTIK nominal `grup`
        // değil, "roster'ında BEN varım" sorgusu önemli (bir sporcu birden fazla, farklı derse kayıtlı
        // olabilir). _sonrakiDersCache (grup->slots) ile KARIŞTIRILMASIN — o hâlâ yönetici yoklama
        // ekranındaki "bu KATEGORİNİN bugünkü dersi" sorgusu için ayrı ve değişmedi.
        let _sporcuKendiDersleriCache = null; // {slots, fetchT}
        function _sporcuKendiSlotlari(ad) {
            if(!_sporcuKendiDersleriCache) return [];
            return _sporcuKendiDersleriCache.slots.filter(function(s) { return (s.katilimcilar||[]).some(function(k){ return k.ad === ad; }); });
        }
        function sonrakiDersRenderla() {
            let el = document.getElementById('sonraki-ders-widget'); if(!el) return;
            let ad = loggedInSporcu || oyunSeciliSporcu || basariSeciliSporcu || ''; if(!ad) { el.innerHTML = ''; return; }
            let slots = _sporcuKendiSlotlari(ad);
            if(!slots.length) { el.innerHTML = ''; return; }
            let sonraki = birSonrakiDersHesapla(slots);
            if(!sonraki) { el.innerHTML = ''; return; }
            let simdi = new Date();
            let bugunGece = new Date(simdi.getFullYear(), simdi.getMonth(), simdi.getDate());
            let hedefGece = new Date(sonraki.tarih.getFullYear(), sonraki.tarih.getMonth(), sonraki.tarih.getDate());
            let gunFarki = Math.round((hedefGece - bugunGece) / 86400000);
            let zamanMetni = gunFarki <= 0 ? 'Bugün' : gunFarki === 1 ? 'Yarın' : gunFarki + ' gün sonra';
            let saatMetni = String(sonraki.tarih.getHours()).padStart(2, '0') + ':' + String(sonraki.tarih.getMinutes()).padStart(2, '0');
            let zilHTML = sonraki.slot.hatirlatmaAktif ? '<span style="font-size:10px; color:var(--neon-green); font-weight:800; margin-left:6px;">🔔</span>' : '';
            el.innerHTML = `<div style="background:var(--bg-panel); border:1px solid var(--border-color); border-radius:12px; padding:12px; margin-bottom:14px; display:flex; align-items:center; gap:10px;">
                <div style="font-size:22px;">📅</div>
                <div><div style="font-size:11px; color:var(--text-muted); font-weight:600;">SIRADAKİ DERSİN</div><div style="font-size:14px; font-weight:800;">${GUN_ADI_TR[sonraki.slot.gun]} ${saatMetni} · <span style="color:var(--accent-orange);">${zamanMetni}</span>${zilHTML}</div></div>
            </div>`;
        }
        function haftalikProgramWidgetGuncelle() {
            let el = document.getElementById('haftalik-program-widget'); if(!el) return;
            let ad = loggedInSporcu || oyunSeciliSporcu || basariSeciliSporcu || '';
            if(!ad || !_sporcuKendiDersleriCache || !_sporcuKendiDersleriCache.slots.length) { el.innerHTML = ''; return; }
            let slotlar = _sporcuKendiDersleriCache.slots.slice().sort(function(a,b){ return a.gun - b.gun || a.baslangicSaat.localeCompare(b.baslangicSaat); });
            let html = '<div class="glass-panel" style="padding:12px; margin-bottom:14px;">'
                + '<div style="font-size:11px; font-weight:700; color:var(--text-muted); margin-bottom:8px;">📅 HAFTALIK PROGRAM</div>';
            slotlar.forEach(function(s) {
                let benimMi = (s.katilimcilar||[]).some(function(k){ return k.ad === ad; });
                let renk = GENEL_RENK;
                html += '<div style="display:flex; align-items:center; gap:9px; padding:7px 9px; border-radius:9px; margin-bottom:5px; ' + (benimMi ? 'border:1px solid ' + renk + '66; background:' + renk + '12;' : 'opacity:.45;') + '">'
                    + '<div style="width:8px; height:8px; border-radius:50%; background:' + renk + '; flex-shrink:0;"></div>'
                    + '<div style="flex:1; font-size:11.5px;"><b>' + GUN_KISA_TR[s.gun] + ' ' + s.baslangicSaat + '</b></div>'
                    + (benimMi ? '<div style="font-size:9px; font-weight:800; color:' + renk + ';">★ SENİN DERSİN</div>' : '')
                    + '</div>';
            });
            html += '</div>';
            el.innerHTML = html;
        }
        function sonrakiDersWidgetGuncelle() {
            let el = document.getElementById('sonraki-ders-widget'); if(!el) return;
            let ad = loggedInSporcu || oyunSeciliSporcu || basariSeciliSporcu || ''; if(!ad) return;
            if(!_sporcuKendiDersleriCache || (Date.now() - _sporcuKendiDersleriCache.fetchT) > 5 * 60000) {
                fetch('/api/antrenman-programi').then(r => r.json()).then(d => {
                    _sporcuKendiDersleriCache = { slots: d.slots || [], fetchT: Date.now() };
                    sonrakiDersRenderla();
                    haftalikProgramWidgetGuncelle();
                }).catch(() => {});
                return;
            }
            sonrakiDersRenderla();
            haftalikProgramWidgetGuncelle();
        }
        function sonrakiDersWidgetBaslat() {
            sonrakiDersWidgetGuncelle();
            setInterval(sonrakiDersWidgetGuncelle, 60000);
        }


        let aktifGrup = 'buyukler'; let grupSuresi = 180; let kalanSure = 180; let audioCtx = null;
        let aktifPlatform = 'sporcu';
        let loggedInSporcu = null; // null = eğitmen/tam yetki; isim = giriş yapan sporcu (sadece kendini görür)
        let detayKarneSporcu = '';
        let secilenSporcu = ""; let aktifCinsiyet = "K"; let aktifYay = "Klasik"; 
        let turnuvaDB = { buyukler: {}, yildizlar: {}, kucukler: {}, minikler: {} }; let takimlarDB = [];
        let silinenlerDB = [];
        // Bayat veri uyarısı: "kimse bir şey değiştirmedi" ile "bağlantım gerçekten koptu" FARKLI
        // şeyler — sadece gerçek WebSocket bağlantı durumuna bakılır, "son mesajdan bu yana geçen süre"ye
        // değil (yoksa sakin bir oturumda bile yanlış alarm verip skor girişini gereksiz yere engeller).
        let _wsKoptuZamani = null;
        const BAYAT_VERI_ESIK_MS = 45 * 1000;
        function bayatVeriKontrol() {
            let banner = document.getElementById('bayat-veri-banner'); if(!banner) return;
            let bagli = !!(window.dagskSync && window.dagskSync.wsBagliMi && window.dagskSync.wsBagliMi());
            if(bagli || !navigator.onLine) { _wsKoptuZamani = null; banner.style.display = 'none'; return; }
            if(!_wsKoptuZamani) _wsKoptuZamani = Date.now();
            banner.style.display = (Date.now() - _wsKoptuZamani > BAYAT_VERI_ESIK_MS) ? 'flex' : 'none';
        }
        document.addEventListener('visibilitychange', () => { if(!document.hidden) setTimeout(bayatVeriKontrol, 1500); });
        // Telefon kilidi açılınca / sekme öne dönünce, WS'in kaçırmış olabileceği davetleri hemen yakala —
        // 25sn'lik periyodik yoklamayı beklemeden.
