            let konumA = grupA.filter(o => o.x != null && o.y != null), konumB = grupB.filter(o => o.x != null && o.y != null);
            let svgBlok = '';
            if(konumA.length >= 2 && konumB.length >= 2) { svgBlok = _isiHaritasiOverlaySVG(konumA, konumB, 'rgba(16,185,129,0.75)', 'rgba(239,68,68,0.8)').svg; }
