        // değişmedi) — ham akış kaydı ise aynı ortamda kusursuz çalıştı, o yüzden bu yönteme geçildi. Gecikme
        // + çizim artık kayıtta yok ama karşılığında TAM, kaydırılabilir bir klip elde ediliyor (canlı 5sn'lik
        // tek kareyle sınırlı değil). Anlık çizimli kareyi ayrıca kaydetmek için bkz. aynaKareKaydet().
        let _aynaKayitAktif = false, _aynaKayitRecorder = null, _aynaKayitParcalar = [], _aynaKayitSayac = 0, _aynaKayitTimer = null, _aynaKayitMime = 'video/webm';
        function aynaKayitBaslat() {
            if(!_aynaStream || _aynaKayitAktif) return;
            _aynaKayitParcalar = [];
            // DÜZELTME: iOS/iPhone'un galeri ve varsayılan video oynatıcısı WebM'i (VP8/VP9) hiç
            // desteklemiyor — indirilen kayıt telefonda açılamıyordu. MP4/H.264 artık hem Safari (iOS 14.3+)
            // hem Chrome tarafından MediaRecorder ile üretilebiliyor ve HER iki platformda da (iPhone dahil)
            // sorunsuz açılıyor — bu yüzden önce MP4 deneniyor, sadece desteklenmiyorsa WebM'e düşülüyor.
            let mime = 'video/mp4';
            if(!MediaRecorder.isTypeSupported(mime)) {
                mime = 'video/webm;codecs=vp9';
                if(!MediaRecorder.isTypeSupported(mime)) mime = 'video/webm';
            }
            try { _aynaKayitRecorder = new MediaRecorder(_aynaStream, { mimeType: mime }); }
            catch(e) { try { _aynaKayitRecorder = new MediaRecorder(_aynaStream); } catch(e2) { showToast('Bu tarayıcıda kayıt desteklenmiyor.', 'error'); return; } }
            _aynaKayitMime = (_aynaKayitRecorder.mimeType || mime);
            _aynaKayitRecorder.ondataavailable = e => { if(e.data.size > 0) _aynaKayitParcalar.push(e.data); };
            _aynaKayitRecorder.onstop = () => {
                if(!_aynaKayitParcalar.length) { showToast('⚠️ Kayıt boş çıktı, tekrar dene.', 'warning'); return; }
                let tipTemiz = _aynaKayitMime.split(';')[0]; // 'video/mp4;codecs=...' -> 'video/mp4'
                let uzanti = tipTemiz.includes('mp4') ? 'mp4' : 'webm';
                let blob = new Blob(_aynaKayitParcalar, { type: tipTemiz });
                let url = URL.createObjectURL(blob);
                let a = document.createElement('a');
                a.href = url; a.download = 'dag-sk-ayna-' + bugunISO() + '-' + Date.now() + '.' + uzanti;
                document.body.appendChild(a); a.click(); document.body.removeChild(a);
                setTimeout(() => URL.revokeObjectURL(url), 4000);
                showToast('🎬 Kayıt indirildi (' + uzanti.toUpperCase() + ')! Telefonundaki "İndirilenler" klasörüne bak.', 'success');
            };
            _aynaKayitRecorder.start();
            _aynaKayitAktif = true;
            _aynaKayitSayac = 0;
            let rozet = document.getElementById('ayna-kayit-rozet'); if(rozet) rozet.style.display = 'inline-flex';
            let sureEl = document.getElementById('ayna-kayit-sure'); if(sureEl) sureEl.textContent = '00:00';
            let bBtn = document.getElementById('ayna-kayit-baslat-btn'); if(bBtn) bBtn.style.display = 'none';
            let dBtn = document.getElementById('ayna-kayit-durdur-btn'); if(dBtn) { dBtn.style.display = 'inline-flex'; dBtn.textContent = '⏹️ Kayıt: 00:00 (Bitir & İndir)'; }
            if(_aynaKayitTimer) clearInterval(_aynaKayitTimer);
            _aynaKayitTimer = setInterval(() => {
                _aynaKayitSayac++;
                let m = String(Math.floor(_aynaKayitSayac / 60)).padStart(2, '0');
                let s = String(_aynaKayitSayac % 60).padStart(2, '0');
                let sureMetni = m + ':' + s;
                let el = document.getElementById('ayna-kayit-sure'); if(el) el.textContent = sureMetni;
                // Sayaç HEM rozette hem de "Bitir" butonunun üzerinde — kaydın gerçekten sürdüğü
                // gözden kaçmasın diye tek bir yere değil, dikkat çeken her iki yere de basılıyor.
                let dBtn2 = document.getElementById('ayna-kayit-durdur-btn'); if(dBtn2) dBtn2.textContent = '⏹️ Kayıt: ' + sureMetni + ' (Bitir & İndir)';
            }, 1000);
            showToast('🔴 Kayıt başladı — üstteki kırmızı rozeti ve buton üzerindeki sayacı izle.', 'success');
            try { sesCal(900, 0.1); } catch(e) {}
        }
        function aynaKayitDurdur() {
            if(!_aynaKayitAktif) return;
            _aynaKayitAktif = false;
            if(_aynaKayitRecorder && _aynaKayitRecorder.state !== 'inactive') { try { _aynaKayitRecorder.stop(); } catch(e) {} }
            if(_aynaKayitTimer) { clearInterval(_aynaKayitTimer); _aynaKayitTimer = null; }
            let rozet = document.getElementById('ayna-kayit-rozet'); if(rozet) rozet.style.display = 'none';
            let bBtn = document.getElementById('ayna-kayit-baslat-btn'); if(bBtn) bBtn.style.display = 'inline-flex';
            let dBtn = document.getElementById('ayna-kayit-durdur-btn'); if(dBtn) { dBtn.style.display = 'none'; dBtn.textContent = '⏹️ Kaydı Bitir & İndir'; }
        }
        // ---- Anlık kare kaydı: gecikmeli+çizim bindirilmiş kanvası TEK KARE olarak PNG indirir —
        // canvas.toDataURL() basit/güvenli bir API, video kaydından farklı olarak çökme riski taşımıyor.
        function aynaKareKaydet() {
            let canvas = document.getElementById('ayna-gecikmeli-canvas'); if(!canvas || !_aynaStream) return;
            try {
                let url = canvas.toDataURL('image/png');
                let a = document.createElement('a');
                a.href = url; a.download = 'dag-sk-ayna-kare-' + bugunISO() + '-' + Date.now() + '.png';
                document.body.appendChild(a); a.click(); document.body.removeChild(a);
                showToast('📸 Kare (çizimlerinle birlikte) kaydedildi!', 'success');
            } catch(e) { showToast('Kare kaydedilemedi.', 'error'); }
        }
        // ---- Tam ekran: gerçek Fullscreen API yerine CSS tabanlı "büyüt" — iOS Safari dahil TÜM
        // cihazlarda güvenilir çalışır (Safari, canvas gibi keyfi elemanlarda native fullscreen'i desteklemiyor).
        // DÜZELTME: position:fixed, kaydırılabilir bir üst konteynerin (bu ekran #icerik-video sekmesi
        // içinde kaydırılıyor) İÇİNDE kaldığında iOS Safari'de gerçek viewport'a değil, o kaydırma
        // konteynerine göre sabitleniyor — bilinen bir WebKit hatası. Bunun yerine öğeyi tam ekrana
