                st.xp += kazanilan; st.oynanan += 1; st.toplamElmas += kazanilan;
                if(st.gunTarih !== rfxBugun()) { st.gunTarih = rfxBugun(); st.gunElmas = 0; } st.gunElmas += kazanilan;
                let yld = kazanilan >= 9 ? 3 : kazanilan >= 5 ? 2 : kazanilan >= 1 ? 1 : 0; if(yld > st.maxYildiz) st.maxYildiz = yld;
